// And groups predicates with the AND operator between them.
func And(predicates ...predicate.GroupBuyRefund) predicate.GroupBuyRefund {
	return predicate.GroupBuyRefund(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.GroupBuyRefund) predicate.GroupBuyRefund {
	return predicate.GroupBuyRefund(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.GroupBuyRefund) predicate.GroupBuyRefund {
	return predicate.GroupBuyRefund(sql.NotPredicates(p))
}
